11	// ForeachAddScalarList Host 端 — 遍历 tensor 列表，为每个 tensor 计算 tiling 并启动 kernel
12	
13	#include "torch_kernel_helper.h"
14	#include "tiling/platform/platform_ascendc.h"
15	#include "aclrtlaunch_foreach_add_scalar_list.h"
16	
17	namespace ascend_kernel {
18	
19	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
20	
21	std::vector<at::Tensor> foreach_add_scalar_list(const std::vector<at::Tensor>& inputs,
22	                                                 const at::Tensor& alpha)
23	{
24	    std::vector<at::Tensor> outputs;
25	    int64_t listLen = static_cast<int64_t>(inputs.size());
26	    outputs.reserve(static_cast<size_t>(listLen));
27	
28	    // ---- 获取硬件参数 ----
29	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
30	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
31	    uint64_t ubSize;
32	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
33	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
34	
35	    // ---- 准备 alpha 值 (统一转为 float32, 移到 CPU 供 host 端读取) ----
36	    at::Tensor alphaCpu = alpha.to(at::kCPU).to(at::kFloat);
37	    const float* alphaData = alphaCpu.const_data_ptr<float>();
38	
39	    for (int64_t k = 0; k < listLen; ++k) {
40	        const at::Tensor& input = inputs[static_cast<size_t>(k)];
41	        float alphaValue = alphaData[static_cast<size_t>(k)];
42	
43	        // ---- 输入校验 ----
44	        auto scalarType = input.scalar_type();
45	        TORCH_CHECK(scalarType == at::kHalf || scalarType == at::kBFloat16 ||
46	                    scalarType == at::kFloat || scalarType == at::kInt ||
47	                    scalarType == at::kLong,
48	                    "foreach_add_scalar_list: only float16, bfloat16, float32, int32, int64 supported, got ",
49	                    scalarType);
50	        TORCH_CHECK(input.is_contiguous(),
51	                    "foreach_add_scalar_list: input tensor must be contiguous");
52	
53	        int64_t totalLength = input.numel();
54	        int64_t dtypeSize = static_cast<int64_t>(input.element_size());
55	
56	        auto output = at::empty_like(input);
57	
58	        if (totalLength == 0) {
59	            outputs.push_back(output);
60	            continue;
61	        }
62	
63	        // ---- 判断是否为浮点类型 ----
64	        bool isFloat = (scalarType == at::kFloat || scalarType == at::kHalf ||
65	                        scalarType == at::kBFloat16);
66	        int64_t isFloatType = isFloat ? 1 : 0;
67	
68	        // ---- int32/int64: 在 host 端转为 float32 调用 kernel, 结果转回原类型 ----
69	        at::Tensor kernelInput = input;
70	        at::Tensor kernelOutput;
71	        at::ScalarType origScalarType = scalarType;
72	        int64_t kernelDtypeSize = dtypeSize;
73	
74	        if (!isFloat && (scalarType == at::kInt || scalarType == at::kLong)) {
75	            // 将 int 类型 input 转为 float32
76	            kernelInput = input.to(at::kFloat);
77	            kernelDtypeSize = static_cast<int64_t>(sizeof(float));  // 4
78	            isFloatType = 1;  // 调用 float32 kernel 路径
79	            kernelOutput = at::empty_like(kernelInput);
80	        } else {
81	            kernelOutput = output;
82	        }
83	
84	        // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
85	        int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
86	        int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
87	                                        / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
88	
89	        int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
90	        int64_t formerNum = usedCoreNum - 1;
91	        int64_t formerLength = totalLengthCoreAlign;
92	        int64_t tailLengthVal = totalLength - formerNum * formerLength;
93	
94	        // ---- UB 级 tiling (核内切分, 32B 对齐) ----
95	        // bufferCoefficient 从 UB 分配表推导:
96	        //   fp32: inQueue(2*4) + outQueue(2*4) = 16
97	        //   fp16/bf16: inQueue(2*2) + outQueue(2*2) + castBufIn(4) + castBufOut(4) = 16
98	        int64_t bufferCoefficient;
99	        if (kernelDtypeSize == 2) {
100	            bufferCoefficient = 16;   // fp16/bf16: cast to fp32
101	        } else {
102	            bufferCoefficient = 16;   // fp32: direct compute
103	        }
104	
105	        int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
106	        int64_t alignElements = 32 / kernelDtypeSize;
107	        if (alignElements < 1) {
108	            alignElements = 1;
109	        }
110	        int64_t tileLength = (maxTileElements / alignElements) * alignElements;
111	
112	        uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
113	
114	        // EXEC_KERNEL_CMD 硬约束: 所有参数必须是左值
115	        EXEC_KERNEL_CMD(foreach_add_scalar_list, blockDim,
116	                        kernelInput, kernelOutput,
117	                        formerNum, formerLength, tailLengthVal, tileLength,
118	                        kernelDtypeSize, isFloatType, alphaValue);
119	
120	        // ---- 将 float32 结果转回原始 int 类型 ----
121	        if (!isFloat && (origScalarType == at::kInt || origScalarType == at::kLong)) {
122	            output = kernelOutput.to(origScalarType);
123	        }
124	
125	        outputs.push_back(output);
126	    }
127	
128	    return outputs;
129	}
130	
131	}  // namespace ascend_kernel
