11	// ForeachAddScalarList AscendC Kernel — 逐元素标量加法
12	// out_i = x_i + alphaValue (alphaValue 为 float32 标量)
13	// 支持: float32 直接计算, float16/bfloat16/int32/int64 经 float32 中间计算
14	// Host 端遍历 tensor 列表，为每个 tensor 独立启动此 kernel
15	
16	#include "kernel_operator.h"
17	
18	constexpr int32_t BUFFER_NUM = 2;
19	
20	template <typename T>
21	class KernelForeachAddScalarList {
22	public:
23	    __aicore__ inline KernelForeachAddScalarList() {}
24	
25	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
26	                                int64_t formerNum, int64_t formerLength,
27	                                int64_t tailLength, int64_t tileLength,
28	                                float alphaValue)
29	    {
30	        int64_t blockIdx = AscendC::GetBlockIdx();
31	
32	        if (blockIdx < formerNum) {
33	            this->blockLength = formerLength;
34	            int64_t offset = formerLength * blockIdx;
35	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
36	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
37	        } else {
38	            this->blockLength = tailLength;
39	            int64_t tailIdx = blockIdx - formerNum;
40	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
41	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
42	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
43	        }
44	
45	        this->tileLength = tileLength;
46	        this->alphaValue = alphaValue;
47	
48	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
49	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
50	
51	        if constexpr (!std::is_same_v<T, float>) {
52	            // fp16/bf16/int32/int64: need fp32 intermediate buffers for upcast
53	            pipe.InitBuffer(castBufIn, tileLength * sizeof(float));
54	            pipe.InitBuffer(castBufOut, tileLength * sizeof(float));
55	        }
56	    }
57	
58	    __aicore__ inline void Process()
59	    {
60	        if (this->blockLength == 0) {
61	            return;
62	        }
63	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
64	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
65	
66	        for (int64_t i = 0; i < tileNum - 1; ++i) {
67	            CopyIn(i, this->tileLength);
68	            Compute(i, this->tileLength);
69	            CopyOut(i, this->tileLength);
70	        }
71	        CopyIn(tileNum - 1, tailTileLength);
72	        Compute(tileNum - 1, tailTileLength);
73	        CopyOut(tileNum - 1, tailTileLength);
74	    }
75	
76	private:
77	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
78	    {
79	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
80	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
81	        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
82	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
83	        inQueueX.EnQue(xLocal);
84	    }
85	
86	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
87	    {
88	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
89	
90	        if constexpr (std::is_same_v<T, float>) {
91	            // float32: compute Adds directly
92	            AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
93	            AscendC::Adds(yLocal, xLocal, this->alphaValue, curTileLength);
94	            outQueueY.EnQue<float>(yLocal);
95	        } else {
96	            // fp16/bf16/int32/int64: Cast up → fp32 → Adds(scalar) → Cast down
97	            AscendC::LocalTensor<float> xLocalFp32 = castBufIn.Get<float>();
98	            AscendC::LocalTensor<float> yLocalFp32 = castBufOut.Get<float>();
99	            AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
100	
101	            // Cast input to float32
102	            AscendC::Cast(xLocalFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
103	            // Compute scalar add in float32
104	            AscendC::Adds(yLocalFp32, xLocalFp32, this->alphaValue, curTileLength);
105	            // Cast back to original dtype
106	            // fp16/bf16: CAST_ROUND for proper rounding; int types: CAST_NONE for truncation
107	            if constexpr (std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
108	                AscendC::Cast(yLocal, yLocalFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
109	            } else {
110	                // int32/int64: CAST_NONE for truncation toward zero
111	                AscendC::Cast(yLocal, yLocalFp32, AscendC::RoundMode::CAST_NONE, curTileLength);
112	            }
113	
114	            outQueueY.EnQue<T>(yLocal);
115	        }
116	        inQueueX.FreeTensor(xLocal);
117	    }
118	
119	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
120	    {
121	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
122	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
123	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
124	        outQueueY.FreeTensor(yLocal);
125	    }
126	
127	private:
128	    AscendC::TPipe pipe;
129	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
130	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
131	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufIn;
132	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufOut;
133	    AscendC::GlobalTensor<T> xGm;
134	    AscendC::GlobalTensor<T> yGm;
135	    int64_t blockLength;
136	    int64_t tileLength;
137	    float alphaValue;
138	};
139	
140	extern "C" __global__ __aicore__ void foreach_add_scalar_list(GM_ADDR x, GM_ADDR y,
141	                                                               int64_t formerNum, int64_t formerLength,
142	                                                               int64_t tailLength, int64_t tileLength,
143	                                                               int64_t dtypeSize, int64_t isFloatType,
144	                                                               float alphaValue)
145	{
146	    if (dtypeSize == 2) {
147	        // fp16 / bfloat16
148	        KernelForeachAddScalarList<half> op;
149	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, alphaValue);
150	        op.Process();
151	    } else if (dtypeSize == 4 && isFloatType != 0) {
152	        // float32
153	        KernelForeachAddScalarList<float> op;
154	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, alphaValue);
155	        op.Process();
156	    } else if (dtypeSize == 4 && isFloatType == 0) {
157	        // int32
158	        KernelForeachAddScalarList<int32_t> op;
159	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, alphaValue);
160	        op.Process();
161	    } else if (dtypeSize == 8) {
162	        // int64
163	        KernelForeachAddScalarList<int64_t> op;
164	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, alphaValue);
165	        op.Process();
166	    }
167	}
