11	// ForeachAddList op_host — per-block tiling + EXEC_KERNEL_CMD launch
12	// Input: flattened 1D tensors (pre-processed by Python wrapper)
13	// Follows official add_custom pattern: blockLength + tileLength tiling
14	
15	#include <algorithm>
16	#include <cstdint>
17	
18	#include <torch/extension.h>
19	#include <torch/library.h>
20	
21	#include "torch_kernel_helper.h"
22	#include "tiling/platform/platform_ascendc.h"
23	
24	#include "aclrtlaunch_foreach_add_list_fp16.h"
25	#include "aclrtlaunch_foreach_add_list_fp32.h"
26	#include "aclrtlaunch_foreach_add_list_bf16.h"
27	
28	namespace ascend_kernel {
29	
30	constexpr int32_t DEFAULT_TILE_LENGTH = 2048;  // 32B-aligned for all dtypes
31	constexpr int32_t DEFAULT_NUM_CORES = 24;
32	constexpr int32_t MIN_BLOCK_LENGTH = DEFAULT_TILE_LENGTH;
33	
34	at::Tensor foreach_add_list(const at::Tensor &x1Flat, const at::Tensor &x2Flat, double alpha)
35	{
36	    TORCH_CHECK(x1Flat.dim() == 1, "x1_flat must be 1D");
37	    TORCH_CHECK(x2Flat.dim() == 1, "x2_flat must be 1D");
38	    TORCH_CHECK(x1Flat.sizes() == x2Flat.sizes(), "x1_flat and x2_flat must have the same shape");
39	    TORCH_CHECK(
40	        x1Flat.scalar_type() == at::kFloat || x1Flat.scalar_type() == at::kHalf ||
41	            x1Flat.scalar_type() == at::kBFloat16,
42	        "x1_flat must be float16, float32, or bfloat16");
43	    TORCH_CHECK(x2Flat.scalar_type() == x1Flat.scalar_type(),
44	        "x2_flat must have the same dtype as x1_flat");
45	    TORCH_CHECK(x1Flat.is_contiguous(), "x1_flat must be contiguous");
46	    TORCH_CHECK(x2Flat.is_contiguous(), "x2_flat must be contiguous");
47	
48	    int32_t totalElems = static_cast<int32_t>(x1Flat.numel());
49	
50	    // Determine number of cores: at least 1, at most DEFAULT_NUM_CORES, but
51	    // each core must get at least MIN_BLOCK_LENGTH elements
52	    int32_t maxCores = std::max<int32_t>(1, totalElems / MIN_BLOCK_LENGTH);
53	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_CORES, maxCores);
54	    usedCoreNum = std::max<int32_t>(1, usedCoreNum);
55	
56	    int32_t tileLength = DEFAULT_TILE_LENGTH;
57	
58	    // Allocate output
59	    at::Tensor out = at::empty_like(x1Flat);
60	
61	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
62	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
63	    float alphaVal = static_cast<float>(alpha);
64	    int32_t blockLength = (totalElems + usedCoreNum - 1) / usedCoreNum; // ceil division
65	
66	    // Dispatch by dtype
67	    if (x1Flat.scalar_type() == at::kHalf) {
68	        EXEC_KERNEL_CMD(foreach_add_list_fp16, blockDim,
69	                        x1Flat, x2Flat, out,
70	                        totalElems, blockLength, tileLength, alphaVal);
71	    } else if (x1Flat.scalar_type() == at::kBFloat16) {
72	        EXEC_KERNEL_CMD(foreach_add_list_bf16, blockDim,
73	                        x1Flat, x2Flat, out,
74	                        totalElems, blockLength, tileLength, alphaVal);
75	    } else {
76	        EXEC_KERNEL_CMD(foreach_add_list_fp32, blockDim,
77	                        x1Flat, x2Flat, out,
78	                        totalElems, blockLength, tileLength, alphaVal);
79	    }
80	
81	    return out;
82	}
