11	// AscendC ForeachAddList kernel — elementwise: out = x1 + x2 * alpha
12	// Supports float32, float16, bfloat16
13	// Follows official add_custom pattern: per-block GlobalTensor + DataCopy
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 2;
18	
19	template <typename T>
20	class ForeachAddListKernel {
21	public:
22	    __aicore__ inline void Init(
23	        GM_ADDR x1GM, GM_ADDR x2GM, GM_ADDR outGM,
24	        int32_t totalElems, int32_t blockLength,
25	        int32_t tileLength, float alpha)
26	    {
27	        this->totalElems = totalElems;
28	        this->blockLength = blockLength;
29	        this->tileLength = tileLength;
30	        this->alpha = alpha;
31	
32	        // Per-block GlobalTensor: each block gets a slice of the total data
33	        int32_t blockIdx = AscendC::GetBlockIdx();
34	        int32_t start = blockIdx * blockLength;
35	        int32_t thisBlockLen = blockLength;
36	        if (start + blockLength > totalElems) {
37	            thisBlockLen = totalElems - start;
38	        }
39	
40	        x1Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x1GM) + start, thisBlockLen);
41	        x2Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x2GM) + start, thisBlockLen);
42	        outGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(outGM) + start, thisBlockLen);
43	
44	        pipe.InitBuffer(x1InQueue_, BUFFER_NUM, tileLength * sizeof(T));
45	        pipe.InitBuffer(x2InQueue_, BUFFER_NUM, tileLength * sizeof(T));
46	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileLength * sizeof(T));
47	
48	        if constexpr (std::is_same_v<T, bfloat16_t>) {
49	            pipe.InitBuffer(castBuf1_, tileLength * sizeof(float));
50	            pipe.InitBuffer(castBuf2_, tileLength * sizeof(float));
51	            pipe.InitBuffer(castOutBuf_, tileLength * sizeof(float));
52	        }
53	
54	        this->tileNum = (thisBlockLen + tileLength - 1) / tileLength;
55	    }
56	
57	    __aicore__ inline void Process()
58	    {
59	        int32_t loopCount = tileNum;
60	        for (int32_t i = 0; i < loopCount; i++) {
61	            CopyIn(i);
62	            Compute(i);
63	            CopyOut(i);
64	        }
65	    }
66	
67	private:
68	    __aicore__ inline void CopyIn(int32_t progress)
69	    {
70	        int32_t offset = progress * tileLength;
71	        int32_t curLen = tileLength;
72	        if (offset + curLen > this->blockLength) {
73	            curLen = this->blockLength - offset;
74	        }
75	        if (curLen <= 0) { return; }
76	
77	        x1InLocal_ = x1InQueue_.AllocTensor<T>();
78	        x2InLocal_ = x2InQueue_.AllocTensor<T>();
79	        AscendC::DataCopyExtParams copyParams{1,
80	            static_cast<uint32_t>(curLen) * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
81	        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
82	        AscendC::DataCopyPad(x1InLocal_, x1Gm_[offset], copyParams, padParams);
83	        AscendC::DataCopyPad(x2InLocal_, x2Gm_[offset], copyParams, padParams);
84	        x1InQueue_.EnQue(x1InLocal_);
85	        x2InQueue_.EnQue(x2InLocal_);
86	    }
87	
88	    __aicore__ inline void Compute(int32_t progress)
89	    {
90	        int32_t curLen = tileLength;
91	        {
92	            int32_t offset = progress * tileLength;
93	            if (offset + curLen > this->blockLength) {
94	                int32_t remaining = this->blockLength - offset;
95	                if (remaining <= 0) { return; }
96	                curLen = remaining;
97	            }
98	        }
99	
100	        x1InLocal_ = x1InQueue_.DeQue<T>();
101	        x2InLocal_ = x2InQueue_.DeQue<T>();
102	        yOutLocal_ = yOutQueue_.AllocTensor<T>();
103	
104	        if constexpr (std::is_same_v<T, bfloat16_t>) {
105	            AscendC::LocalTensor<float> x1Fp32 = castBuf1_.Get<float>();
106	            AscendC::LocalTensor<float> x2Fp32 = castBuf2_.Get<float>();
107	            AscendC::LocalTensor<float> yFp32 = castOutBuf_.Get<float>();
108	
109	            AscendC::Cast(x1Fp32, x1InLocal_, AscendC::RoundMode::CAST_NONE, curLen);
110	            AscendC::PipeBarrier<PIPE_V>();
111	            AscendC::Cast(x2Fp32, x2InLocal_, AscendC::RoundMode::CAST_NONE, curLen);
112	            AscendC::PipeBarrier<PIPE_V>();
113	
114	            AscendC::Muls(x2Fp32, x2Fp32, alpha, curLen);
115	            AscendC::PipeBarrier<PIPE_V>();
116	            AscendC::Add(yFp32, x1Fp32, x2Fp32, curLen);
117	            AscendC::PipeBarrier<PIPE_V>();
118	
119	            AscendC::Cast(yOutLocal_, yFp32, AscendC::RoundMode::CAST_ROUND, curLen);
120	            AscendC::PipeBarrier<PIPE_V>();
121	        } else {
122	            AscendC::Muls(x2InLocal_, x2InLocal_, static_cast<T>(alpha), curLen);
123	            AscendC::PipeBarrier<PIPE_V>();
124	            AscendC::Add(yOutLocal_, x1InLocal_, x2InLocal_, curLen);
125	            AscendC::PipeBarrier<PIPE_V>();
126	        }
127	
128	        x1InQueue_.FreeTensor(x1InLocal_);
129	        x2InQueue_.FreeTensor(x2InLocal_);
130	        yOutQueue_.EnQue<T>(yOutLocal_);
131	    }
132	
133	    __aicore__ inline void CopyOut(int32_t progress)
134	    {
135	        int32_t curLen = tileLength;
136	        {
137	            int32_t offset = progress * tileLength;
138	            if (offset + curLen > this->blockLength) {
139	                int32_t remaining = this->blockLength - offset;
140	                if (remaining <= 0) { return; }
141	                curLen = remaining;
142	            }
143	        }
144	
145	        yOutLocal_ = yOutQueue_.DeQue<T>();
146	        AscendC::DataCopyExtParams copyParams{1,
147	            static_cast<uint32_t>(curLen) * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
148	        AscendC::DataCopyPad(outGm_[progress * tileLength], yOutLocal_, copyParams);
149	        yOutQueue_.FreeTensor(yOutLocal_);
150	    }
151	
152	private:
153	    int32_t totalElems = 0;
154	    int32_t blockLength = 0;
155	    int32_t tileLength = 0;
156	    int32_t tileNum = 0;
157	    float alpha = 1.0f;
158	
159	    AscendC::TPipe pipe;
160	    AscendC::GlobalTensor<T> x1Gm_;
161	    AscendC::GlobalTensor<T> x2Gm_;
162	    AscendC::GlobalTensor<T> outGm_;
163	
164	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x1InQueue_;
165	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> x2InQueue_;
166	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
167	
168	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf1_;
169	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf2_;
170	    AscendC::TBuf<AscendC::TPosition::VECCALC> castOutBuf_;
171	
172	    AscendC::LocalTensor<T> x1InLocal_;
173	    AscendC::LocalTensor<T> x2InLocal_;
174	    AscendC::LocalTensor<T> yOutLocal_;
175	};
176	
177	// =========================================================================
178	// Kernel entry points
179	// =========================================================================
180	
181	extern "C" __global__ __aicore__ void foreach_add_list_fp16(
182	    GM_ADDR x1GM, GM_ADDR x2GM, GM_ADDR outGM,
183	    int32_t totalElems, int32_t blockLength,
184	    int32_t tileLength, float alpha)
185	{
186	    ForeachAddListKernel<half> kernel;
187	    kernel.Init(x1GM, x2GM, outGM, totalElems, blockLength, tileLength, alpha);
188	    kernel.Process();
189	}
190	
191	extern "C" __global__ __aicore__ void foreach_add_list_fp32(
192	    GM_ADDR x1GM, GM_ADDR x2GM, GM_ADDR outGM,
193	    int32_t totalElems, int32_t blockLength,
194	    int32_t tileLength, float alpha)
195	{
196	    ForeachAddListKernel<float> kernel;
197	    kernel.Init(x1GM, x2GM, outGM, totalElems, blockLength, tileLength, alpha);
198	    kernel.Process();
199	}
200	
201	extern "C" __global__ __aicore__ void foreach_add_list_bf16(
202	    GM_ADDR x1GM, GM_ADDR x2GM, GM_ADDR outGM,
203	    int32_t totalElems, int32_t blockLength,
204	    int32_t tileLength, float alpha)
205	{
206	    ForeachAddListKernel<bfloat16_t> kernel;
207	    kernel.Init(x1GM, x2GM, outGM, totalElems, blockLength, tileLength, alpha);
208	    kernel.Process();
209	}
