// ForeachMinimumList Host 端 — 遍历 tensor 列表，为每对 tensor 计算 tiling 并启动 kernel

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_foreach_minimum_list.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

std::vector<at::Tensor> foreach_minimum_list(const std::vector<at::Tensor>& inputs1,
                                               const std::vector<at::Tensor>& inputs2)
{
    int64_t listLen = static_cast<int64_t>(inputs1.size());
    TORCH_CHECK(listLen == static_cast<int64_t>(inputs2.size()),
                "foreach_minimum_list: inputs1 and inputs2 must have the same length");

    std::vector<at::Tensor> outputs;
    outputs.reserve(static_cast<size_t>(listLen));

    // ---- 获取硬件参数 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    for (int64_t k = 0; k < listLen; ++k) {
        const at::Tensor& input1 = inputs1[static_cast<size_t>(k)];
        const at::Tensor& input2 = inputs2[static_cast<size_t>(k)];

        // ---- 输入校验 ----
        auto scalarType = input1.scalar_type();
        TORCH_CHECK(scalarType == at::kHalf || scalarType == at::kBFloat16 ||
                    scalarType == at::kFloat || scalarType == at::kInt,
                    "foreach_minimum_list: only float16, bfloat16, float32, int32 supported, got ",
                    scalarType);
        TORCH_CHECK(input2.scalar_type() == scalarType,
                    "foreach_minimum_list: inputs1 and inputs2 must have the same dtype");
        TORCH_CHECK(input1.sizes() == input2.sizes(),
                    "foreach_minimum_list: inputs1 and inputs2 must have the same shape for each pair");
        TORCH_CHECK(input1.is_contiguous(),
                    "foreach_minimum_list: input1 tensor must be contiguous");
        TORCH_CHECK(input2.is_contiguous(),
                    "foreach_minimum_list: input2 tensor must be contiguous");

        int64_t totalLength = input1.numel();
        int64_t dtypeSize = static_cast<int64_t>(input1.element_size());

        auto output = at::empty_like(input1);

        if (totalLength == 0) {
            outputs.push_back(output);
            continue;
        }

        // ---- 判断是否为浮点类型 ----
        bool isFloat = (scalarType == at::kFloat || scalarType == at::kHalf ||
                        scalarType == at::kBFloat16);
        int64_t isFloatType = isFloat ? 1 : 0;

        // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
        int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
        int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                        / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

        int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
        int64_t formerNum = usedCoreNum - 1;
        int64_t formerLength = totalLengthCoreAlign;
        int64_t tailLengthVal = totalLength - formerNum * formerLength;

        // ---- UB 级 tiling (核内切分, 32B 对齐) ----
        // bufferCoefficient 从 UB 分配表推导:
        //   fp32/int32: inQueueX(2*4) + inQueueY(2*4) + outQueueZ(2*4) = 24
        //               加 2 个 TBuf(4) = 32
        //   fp16/bf16: inQueueX(2*2) + inQueueY(2*2) + outQueueZ(2*2) = 12
        //             加 3 个 castBuf(4) = 12+12 = 24
        int64_t bufferCoefficient;
        if (dtypeSize == 2) {
            bufferCoefficient = 24;  // fp16/bf16: cast to fp32
        } else {
            bufferCoefficient = 32;  // fp32/int32: direct compute
        }

        int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
        int64_t alignElements = 32 / dtypeSize;
        if (alignElements < 1) {
            alignElements = 1;
        }
        int64_t tileLength = (maxTileElements / alignElements) * alignElements;

        uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

        // EXEC_KERNEL_CMD 硬约束: 所有参数必须是左值
        EXEC_KERNEL_CMD(foreach_minimum_list, blockDim,
                        input1, input2, output,
                        formerNum, formerLength, tailLengthVal, tileLength,
                        dtypeSize, isFloatType);

        outputs.push_back(output);
    }

    return outputs;
}

}  // namespace ascend_kernel
