// ForeachMinimumList Host — tiling + EXEC_KERNEL_CMD launch
// Input: two flat 1D tensors (all tensor pairs concatenated by Python wrapper)
// Kernel: elementwise min(x, y) for each pair of elements

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_foreach_minimum_list.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor foreach_minimum_list(const at::Tensor &xFlat, const at::Tensor &yFlat)
{
    // ---- 输入校验 ----
    TORCH_CHECK(xFlat.dim() == 1, "foreach_minimum_list: x_flat must be 1D");
    TORCH_CHECK(yFlat.dim() == 1, "foreach_minimum_list: y_flat must be 1D");
    TORCH_CHECK(xFlat.sizes() == yFlat.sizes(),
                "foreach_minimum_list: x_flat and y_flat must have the same shape");

    auto scalarType = xFlat.scalar_type();
    TORCH_CHECK(scalarType == at::kHalf || scalarType == at::kBFloat16 ||
                scalarType == at::kFloat || scalarType == at::kInt,
                "foreach_minimum_list: only float16, bfloat16, float32, int32 supported, got ",
                scalarType);
    TORCH_CHECK(yFlat.scalar_type() == scalarType,
                "foreach_minimum_list: x_flat and y_flat must have the same dtype");
    TORCH_CHECK(xFlat.is_contiguous(), "foreach_minimum_list: x_flat must be contiguous");
    TORCH_CHECK(yFlat.is_contiguous(), "foreach_minimum_list: y_flat must be contiguous");

    int64_t totalLength = xFlat.numel();
    int64_t dtypeSize = static_cast<int64_t>(xFlat.element_size());

    auto output = at::empty_like(xFlat);

    if (totalLength == 0) {
        return output;
    }

    // ---- 判断是否为浮点类型 ----
    bool isFloat = (scalarType == at::kFloat || scalarType == at::kHalf ||
                    scalarType == at::kBFloat16);
    int64_t isFloatType = isFloat ? 1 : 0;

    // ---- 获取硬件参数 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLengthVal = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分, 32B 对齐) ----
    // bufferCoefficient 从设计文档 UB 分配表推导:
    //   fp32/int32: 32
    //   fp16/bf16: 24
    int64_t bufferCoefficient;
    if (dtypeSize == 2) {
        bufferCoefficient = 24;   // fp16/bf16: inQueueX*4 + inQueueY*4 + outQueueZ*4 + castBuf*12
    } else {
        bufferCoefficient = 32;   // fp32/int32: inQueueX*8 + inQueueY*8 + outQueueZ*8 + tmpBuf*8
    }

    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements < 1) {
        alignElements = 1;
    }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // EXEC_KERNEL_CMD 硬约束: 所有参数必须是左值
    EXEC_KERNEL_CMD(foreach_minimum_list, blockDim,
                    xFlat, yFlat, output,
                    formerNum, formerLength, tailLengthVal, tileLength,
                    dtypeSize, isFloatType);

    return output;
}

}  // namespace ascend_kernel
